def pattern_match(value,patterns):
    if not patterns:return True
    values=value or []
    for p in patterns:
        if p=='none' and not values:return True
        if p=='any' and values:return True
        if p.startswith('*') and p.endswith('*') and len(p)>2:
            if any(p[1:-1].lower() in x.lower() for x in values):return True
        elif p.startswith('*'):
            if any(x.lower().endswith(p[1:].lower()) for x in values):return True
        elif p.endswith('*'):
            if any(x.lower().startswith(p[:-1].lower()) for x in values):return True
        elif any(x.lower()==p.lower() for x in values):return True
    return False

def parse_clock(value,default):
    if value=='':return default
    m=re.fullmatch(r'(\d{1,2})(\d{2})(am|pm)?',value,re.I)
    if not m:return None
    hour,minute=int(m[1]),int(m[2]);ampm=(m[3] or '').lower()
    if minute>59:return None
    if ampm:hour=hour%12+(12 if ampm=='pm' else 0)
    if hour>24 or (hour==24 and minute):return None
    return hour*60+minute

def parse_slot(value):
    m=re.fullmatch(r'(\d+)(m|h)?',value or '')
    if not m:return 30
    return int(m[1])*(60 if m[2]=='h' else 1)

